/**
 * GetVar eval — fixture-driven test (phase 2f medium Stop β Task 2).
 *
 * Tests the `GetVar` arm of the evaluator. GetVar is a leaf arm that reads
 * `ctx.extension.values[varId]`:
 *   - absent  → SValue Option(None)
 *   - present + matching tpe → SValue Option(Some(value))
 *   - present + mismatched tpe → throws 'get-var-type-mismatch'
 *
 * Fixtures generated by `fixture-gen/src/cmds/ergoscript/eval/get_var.rs`
 * (sigma-rust oracle; byte-equality check).
 */

import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { parseTree } from '../../src/wire/ergo-tree'
import { evaluate, evaluateWith } from '../../src/eval/evaluate'
import { makeContext } from '../../src/eval/eval-context'
import { hexToBytes, hydrateSValue, captureEvalError, rehydrateEvalOpts } from '../_helpers'

const __dirname = dirname(fileURLToPath(import.meta.url))

interface GetVarFixtureEntry {
  name: string
  tree_bytes_hex: string
  opts_json: Record<string, unknown>
  expected_value_json: unknown
  expected_cost: number
  expected_error_code: string | null
}

interface GetVarFixtureFile {
  corpus: string
  entries: GetVarFixtureEntry[]
}

const FIXTURE_PATH = join(__dirname, '../fixtures/eval/get-var.json')
const fixture: GetVarFixtureFile = JSON.parse(readFileSync(FIXTURE_PATH, 'utf-8'))


describe('GetVar eval (phase 2f medium Stop β Task 2)', () => {
  for (const entry of fixture.entries) {
    it(entry.name, () => {
      const tree = parseTree(hexToBytes(entry.tree_bytes_hex))
      const opts = rehydrateEvalOpts(entry.opts_json)
      const ctx = makeContext(opts)

      if (entry.expected_error_code !== null) {
        const err = captureEvalError(() => evaluateWith(tree, ctx))
        expect(err.code).toBe(entry.expected_error_code)
      } else {
        const result = evaluateWith(tree, ctx)
        expect(result).toEqual(hydrateSValue(entry.expected_value_json))
        expect(ctx.jitCost).toBe(entry.expected_cost)
      }
    })
  }

  it("GetVar without ctx.extension throws 'context-field-missing'", () => {
    // Build a synthetic ErgoTree with a GetVar node using v0 header.
    // tree_bytes_hex = "00e30304" = v0 header + OP_GET_VAR(0xe3) + varId=3 + SInt(0x04)
    const treeBytes = hexToBytes('00e30304')
    const tree = parseTree(treeBytes)
    // No extension in context (extension is undefined by default).
    const err = captureEvalError(() => evaluate(tree))
    expect(err.code).toBe('context-field-missing')
  })
})
